import { Field as FieldPrimitive, useField, useFieldContext } from '@ark-ui/solid/field';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import type { JSX } from 'solid-js';
import { createEffect, splitProps } from 'solid-js';
import styles from './Field.module.css';

type FieldItemProps = ComponentProps<typeof FieldPrimitive.Item> & ComponentProps<'div'>;
type FieldInputProps = ComponentProps<typeof FieldPrimitive.Input> & {
  defaultValue?: string | number | readonly string[];
};
type FieldTextareaProps = ComponentProps<typeof FieldPrimitive.Textarea> & {
  defaultValue?: string | number | readonly string[];
};
type FieldSelectProps = ComponentProps<typeof FieldPrimitive.Select> & {
  defaultValue?: ComponentProps<typeof FieldPrimitive.Select>['value'];
};
type FieldSelectPrimitiveProps = ComponentProps<typeof FieldPrimitive.Select> & {
  'prop:defaultValue'?: FieldSelectProps['defaultValue'];
};

const FieldSelectPrimitive = FieldPrimitive.Select as (
  props: FieldSelectPrimitiveProps,
) => JSX.Element;

function Field(props: ComponentProps<typeof FieldPrimitive.Root>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldPrimitive.Root
      asChild={local.asChild}
      {...others}
      data-slot="field-root"
      class={clsx(styles.root, local.class)}
    />
  );
}

function FieldRootProvider(props: ComponentProps<typeof FieldPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldPrimitive.RootProvider
      asChild={local.asChild}
      {...others}
      data-slot="field-root-provider"
      class={clsx(styles.root, local.class)}
    />
  );
}

function FieldItem(props: FieldItemProps) {
  const [local, others] = splitProps(props, ['children', 'class', 'ref', 'value']);

  return (
    <FieldPrimitive.Item value={local.value}>
      <div
        {...others}
        data-slot="field-item"
        class={clsx(styles.item, local.class)}
        ref={local.ref}
      >
        {local.children}
      </div>
    </FieldPrimitive.Item>
  );
}

function FieldLabel(props: ComponentProps<typeof FieldPrimitive.Label>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldPrimitive.Label
      asChild={local.asChild}
      {...others}
      data-slot="field-label"
      class={clsx(styles.label, local.class)}
    />
  );
}

function FieldInput(props: FieldInputProps) {
  const [local, others] = splitProps(props, ['asChild', 'class', 'defaultValue', 'ref']);
  let inputRef: HTMLInputElement | undefined;

  createEffect(() => {
    if (inputRef) inputRef.defaultValue = String(local.defaultValue ?? '');
  });

  return (
    <FieldPrimitive.Input
      asChild={local.asChild}
      {...others}
      {...(local.asChild ? { 'prop:defaultValue': local.defaultValue } : {})}
      data-slot="field-input"
      class={clsx(styles.control, local.class)}
      ref={(element) => {
        inputRef = element;
        if (typeof local.ref === 'function') local.ref(element);
      }}
    />
  );
}

function FieldTextarea(props: FieldTextareaProps) {
  const [local, others] = splitProps(props, ['asChild', 'class', 'defaultValue', 'ref']);
  let textareaRef: HTMLTextAreaElement | undefined;

  createEffect(() => {
    if (textareaRef) textareaRef.defaultValue = String(local.defaultValue ?? '');
  });

  return (
    <FieldPrimitive.Textarea
      asChild={local.asChild}
      {...others}
      {...(local.asChild ? { 'prop:defaultValue': local.defaultValue } : {})}
      data-slot="field-textarea"
      class={clsx(styles.control, styles.textarea, local.class)}
      ref={(element) => {
        textareaRef = element;
        if (typeof local.ref === 'function') local.ref(element);
      }}
    />
  );
}

function FieldSelect(props: FieldSelectProps) {
  const [local, others] = splitProps(props, ['asChild', 'class', 'defaultValue', 'ref']);
  let selectRef: HTMLSelectElement | undefined;

  createEffect(() => {
    const defaultValue = local.defaultValue;

    if (!selectRef || defaultValue === undefined) return;

    const values = new Set(
      (Array.isArray(defaultValue) ? defaultValue : [defaultValue]).map((value) => String(value)),
    );

    for (const option of Array.from(selectRef.options)) {
      const selected = values.has(option.value);
      option.selected = selected;
      option.defaultSelected = selected;
    }
  });

  return (
    <FieldSelectPrimitive
      asChild={local.asChild}
      {...others}
      prop:defaultValue={local.defaultValue}
      data-slot="field-select"
      class={clsx(styles.control, local.class)}
      ref={(element) => {
        selectRef = element;
        if (typeof local.ref === 'function') local.ref(element);
      }}
    />
  );
}

function FieldHelperText(props: ComponentProps<typeof FieldPrimitive.HelperText>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldPrimitive.HelperText
      asChild={local.asChild}
      {...others}
      data-slot="field-helper-text"
      class={clsx(styles.helperText, local.class)}
    />
  );
}

function FieldErrorText(props: ComponentProps<typeof FieldPrimitive.ErrorText>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldPrimitive.ErrorText
      asChild={local.asChild}
      {...others}
      data-slot="field-error-text"
      class={clsx(styles.errorText, local.class)}
    />
  );
}

function FieldRequiredIndicator(props: ComponentProps<typeof FieldPrimitive.RequiredIndicator>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <FieldPrimitive.RequiredIndicator
      asChild={local.asChild}
      {...others}
      data-slot="field-required-indicator"
      class={clsx(styles.requiredIndicator, local.class)}
    />
  );
}

const FieldContext = FieldPrimitive.Context;

export {
  Field,
  FieldContext,
  FieldErrorText,
  FieldHelperText,
  FieldInput,
  FieldItem,
  FieldLabel,
  FieldRequiredIndicator,
  FieldRootProvider,
  FieldSelect,
  FieldTextarea,
  useField,
  useFieldContext,
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--moduix-field-gap, var(--moduix-spacing-1));
    width: var(--moduix-field-width, 100%);
    max-width: var(--moduix-field-max-width, none);
    color: var(--moduix-field-color, var(--moduix-color-foreground));

    &[data-disabled] {
      opacity: var(--moduix-field-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .item {
    display: grid;
    gap: var(--moduix-field-item-gap, var(--moduix-spacing-1));
  }

  .label {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-field-label-gap, var(--moduix-spacing-2));
    overflow-wrap: anywhere;
    color: var(--moduix-field-label-color, var(--moduix-color-foreground));
    font-size: var(--moduix-field-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-field-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-field-label-line-height, var(--moduix-line-height-text-sm));
  }

  .helperText {
    margin: 0;
    overflow-wrap: anywhere;
    color: var(--moduix-field-description-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-field-description-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-field-description-line-height, var(--moduix-line-height-text-sm));
  }

  .control {
    box-sizing: border-box;
    width: var(--moduix-field-control-width, 100%);
    min-height: var(--moduix-field-control-height, var(--moduix-size-md));
    margin: 0;
    border: var(--moduix-field-control-border-width, var(--moduix-border-width-sm))
      var(--moduix-field-control-border-style, solid)
      var(--moduix-field-control-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-field-control-radius, var(--moduix-radius-md));
    padding: var(--moduix-field-control-padding-y, var(--moduix-spacing-1))
      var(--moduix-field-control-padding-x, var(--moduix-spacing-3-5));
    background-color: var(--moduix-field-control-bg, var(--moduix-color-background));
    color: var(--moduix-field-control-color, var(--moduix-color-foreground));
    font: inherit;
    font-size: var(--moduix-field-control-font-size, var(--moduix-text-md));
    line-height: var(--moduix-field-control-line-height, var(--moduix-line-height-text-md));
    outline: var(
        --moduix-field-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: var(--moduix-field-focus-ring-offset, var(--moduix-focus-ring-inset-offset));
    transition:
      border-color var(--moduix-field-control-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-field-control-transition, var(--moduix-transition-default));

    &::placeholder {
      color: var(--moduix-field-control-placeholder-color, var(--moduix-color-muted-foreground));
    }

    &:focus-visible {
      outline-color: var(--moduix-field-focus-ring-color, var(--moduix-color-ring));
    }

    &[data-invalid] {
      border-color: var(
        --moduix-field-control-border-color-invalid,
        var(--moduix-color-destructive)
      );

      &:focus-visible {
        outline-color: var(
          --moduix-field-control-border-color-invalid,
          var(--moduix-color-destructive)
        );
      }
    }

    &[data-disabled],
    &:disabled {
      pointer-events: none;
    }
  }

  .textarea {
    min-height: var(--moduix-field-textarea-min-height, 5rem);
    resize: vertical;
  }

  .errorText {
    margin: 0;
    overflow-wrap: anywhere;
    color: var(--moduix-field-error-color, var(--moduix-color-destructive));
    font-size: var(--moduix-field-error-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-field-error-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-field-error-line-height, var(--moduix-line-height-text-sm));
  }

  .requiredIndicator {
    color: var(--moduix-field-required-indicator-color, var(--moduix-color-destructive));
  }
}
